/*
* Permet d'accéder aux bornes du sous-tableau de array_NCB qui contient les numéros de combinaisons 'couleur' faisant intevenir la carte en question
* NC : le numéro de la carte jouée
* POS: [ index dans la table array_NCB, nombre de combinaisons dans laquelle la carte apparait ]
* Implémenté comme un tableau 1D (nombre_de_carte*2)
*/

constexpr std::array<int, 108> NC_to_POS = { 0, 27, 27, 26, 53, 25, 78, 25, 103, 25, 128, 25, 153, 25, 178, 26, 204, 27, 231, 27, 258, 26, 284, 25, 309, 25, 334, 25, 359, 25, 384, 25, 409, 26, 435, 27, 462, 27, 489, 26, 515, 25, 540, 25, 565, 25, 590, 25, 615, 25, 640, 26, 666, 27, 693, 27, 720, 26, 746, 25, 771, 25, 796, 25, 821, 25, 846, 25, 871, 26, 897, 27, 924, 27, 951, 26, 977, 25, 1002, 25, 1027, 25, 1052, 25, 1077, 25, 1102, 26, 1128, 27, 1155, 27, 1182, 26, 1208, 25, 1233, 25, 1258, 25, 1283, 25, 1308, 25, 1333, 26, 1359, 27 };

ColorManager::ColorManager() : CMB_exist(0), highest_existing_index_cmb(nbColorCMB - 1) {

	CMB_exist.set();

};

ColorManager::~ColorManager() {

};

void ColorManager::reset() {

	CMB_exist.set();
	highest_existing_index_cmb = nbColorCMB - 1;

	return;
};

void ColorManager::update(int card) {

	if (highest_existing_index_cmb == -1) return;

	int firstIndex = NC_to_POS[card * 2 + 0], CMBSize = NC_to_POS[card * 2 + 1];

	// Voir color_manager.h pour plus d'informations
	// Ne pas utiliser la variable i directement mais toujours array_NCB[i]

	for (int i=firstIndex; i < firstIndex + CMBSize; i++) {

		if (CMB_exist[array_NCB[i]]) CMB_exist[array_NCB[i]] = false;

		if (array_NCB[i] == highest_existing_index_cmb) {
			highest_existing_index_cmb--;
			for (; highest_existing_index_cmb >= 0; highest_existing_index_cmb--) {
				if (CMB_exist[highest_existing_index_cmb]) {
					break;
				}
			}
			// On break parce que les valeurs sont rangées dans l'ordre croissant. Donc si on est arrivé à la plus haute cmb qui existe, toutes celles plus hautes n'existent plus
			break;
		}
		// Si on a dépassé la plus haute combinaison existant encore plus besoin plus besoin
		else if (array_NCB[i] >= highest_existing_index_cmb) break;
	}

	return;
};

int ColorManager::getHighestRank() const {
	if (highest_existing_index_cmb == -1) return -1;
	return NCB_to_RANK[highest_existing_index_cmb] + MODCARDS * couleur;

};